        const d = f === 0.5 ? `M${cx} ${cy - r}A${r} ${r} 0 0 1 ${cx} ${cy + r}Z` : `M${cx} ${cy - r}A${r} ${r} 0 0 1 ${cx} ${cy + r}A${rx.toFixed(1)} ${r} 0 0 ${s} ${cx} ${cy - r}Z`;
