  const MK = mkr('v2a', 'currentColor') + mkr('v2R', RED) + mkr('v2B', BLUE) + mkr('v2G', GRY) + mkr('v2N', GRN);
  const mid = c => (c === RED ? 'v2R' : c === BLUE ? 'v2B' : c === GRY ? 'v2G' : c === GRN ? 'v2N' : 'v2a');
  const sv = (h, label, body) => `<svg viewBox="0 0 300 ${h}" role="img" aria-label="${label}" style="font-size:13px"><defs>${MK}</defs>${body}</svg>`;
