  const e = (x, y, s, o = '') => `<text x="${x}" y="${y}" text-anchor="end" ${o}>${s}</text>`;
  const B = 'font-weight="700"';
  const ln = (x1, y1, x2, y2, col = 'currentColor', w = 2, ex = '') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" ${ex}/>`;
  const rc = (x, y, w, h, fill = 'none', stroke = 'currentColor', ex = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${fill}" stroke="${stroke}" stroke-width="2" ${ex}/>`;
  const dot = (x, y, r, fill, stroke = 'none') => `<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`;
  const ar = (x1, y1, x2, y2, col = 'currentColor', w = 2.4, ex = '') => `<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${col}" stroke-width="${w}" marker-end="url(#${mid(col)})" ${ex}/>`;

