  F["p6-water-share"] = "<svg viewBox=\"0 0 300 173\" role=\"img\" aria-label=\"น้ำบนโลกเป็นน้ำเค็มประมาณ 97 เปอร์เซ็นต์ น้ำจืดประมาณ 3 เปอร์เซ็นต์ และน้ำจืดส่วนใหญ่เป็นน้ำแข็ง\" style=\"font-size:13px\"><defs><marker id=\"ah\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"currentColor\"/></marker><marker id=\"ahR\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"#b91c1c\"/></marker><marker id=\"ahB\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"#1d4ed8\"/></marker><marker id=\"ahG\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"#64748b\"/></marker><marker id=\"ahN\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"#15803d\"/></marker><marker id=\"ahO\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10z\" fill=\"#c2410c\"/></marker></defs><text x=\"150\" y=\"13.3\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">น้ำทั้งหมดบนโลก (ประมาณ)</text><g transform=\"scale(0.8332999999999999)\"><rect x=\"20\" y=\"26\" width=\"310\" height=\"26\" fill=\"#bfdbfe\" stroke=\"currentColor\" stroke-width=\"2\" /><rect x=\"330\" y=\"26\" width=\"10\" height=\"26\" fill=\"#34d399\" stroke=\"currentColor\" stroke-width=\"2\" /></g><text x=\"145.8\" y=\"36.7\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">น้ำเค็ม ประมาณ 97%</text><g transform=\"scale(0.8332999999999999)\"><line x1=\"335\" y1=\"54\" x2=\"335\" y2=\"70\" stroke=\"#15803d\" stroke-width=\"1.5\" /></g><text x=\"188.3\" y=\"66.7\" font-size=\"12\" font-weight=\"700\" fill=\"#15803d\">น้ำจืด ประมาณ 3%</text><text x=\"150\" y=\"86.7\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">น้ำจืดทั้งหมด (ขยาย)</text><g transform=\"scale(0.8332999999999999)\"><rect x=\"20\" y=\"112\" width=\"206\" height=\"26\" fill=\"#e0f2fe\" stroke=\"currentColor\" stroke-width=\"2\" /><rect x=\"226\" y=\"112\" width=\"104\" height=\"26\" fill=\"#6ee7b7\" stroke=\"currentColor\" stroke-width=\"2\" /></g><text x=\"102.5\" y=\"108.3\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">น้ำแข็ง ธารน้ำแข็ง (ส่วนใหญ่)</text><text x=\"231.7\" y=\"108.3\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">น้ำใต้ดิน อื่น ๆ</text><text x=\"150\" y=\"131.7\" font-size=\"12\" text-anchor=\"middle\">น้ำที่ใช้ประโยชน์ได้ง่าย (แม่น้ำ ทะเลสาบ น้ำบาดาล)</text><text x=\"150\" y=\"147.3\" font-size=\"12\" text-anchor=\"middle\">มีน้อยมาก</text><text x=\"150\" y=\"163.8\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">จึงต้องช่วยกันใช้น้ำอย่างประหยัด</text></svg>";
